    {
      "conditions": [],
      "definition":"A core interface is any shared contract/carrier materially governing runtime closure, reporting/status truth, topology/frame progression, proof/qualification, event/projection semantics, identity/binding resolution or provider/resolver behaviour. A change affecting how multiple surfaces decide current truth is a core-interface change.",
      "exceptions": [],
      "grounding": [
        {
          "end_line":1408,
          "quote":"A core interface is any shared contract or carrier that materially governs\nruntime closure, reporting or status truth, topology or frame progression,\nproof or qualification outcome, event or projection semantics, identity or\nbinding resolution, or provider or resolver behaviour. If changing the\ninterface can alter how multiple surfaces decide what is true now, it is a\ncore interface change (P3).",
          "section_id":"repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/SPEC_METHOD.md#SPEC_METHOD%2F7.%20Migration%2FWhat%20counts%20as%20a%20core%20interface",
          "start_line":1403
